def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, max(8.0, DAILY_SALARY * 0.22)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY_PLACEHOLDER() if False else None)
    scarcity = 1.0 - ((float(supply) - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency >= 3:
        target = max(DAILY_SALARY * 1.05, highest_prev + 3.0)
    elif urgency == 2:
        target = max(DAILY_SALARY * 0.82, highest_prev + 1.6)
    elif urgency == 1:
        target = max(DAILY_SALARY * 0.58 + scarcity * 10.0, avg_prev * 0.92)
    else:
        target = DAILY_SALARY * (0.34 + 0.18 * scarcity)
        if desperate_count >= 2:
            target += 6.0
        if rich_count >= 2:
            target += 4.0

    if highest_prev >= 100 and urgency == 0:
        target = min(target, DAILY_SALARY * 0.42)
    elif highest_prev >= 100 and urgency == 1:
        target = min(max(target, DAILY_SALARY * 0.62), DAILY_SALARY * 0.78)

    if day >= 8:
        target += 5.0 * urgency
    if day >= 9 and hp <= 4:
        target += 10.0

    reserve = 0.0
    if hp >= 7 and no_water == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp >= 5:
        reserve = DAILY_SALARY * 0.7

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 2:
        max_affordable = budget

    bid = min(target, max_affordable)

    if urgency >= 2 and bid < DAILY_SALARY * 0.72:
        bid = min(budget, DAILY_SALARY * 0.72)
    if urgency >= 3 and bid < highest_prev + 1.0:
        bid = min(budget, highest_prev + 1.0)

    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)
    my_no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.45))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Compute pressure from yesterday
    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    # Base bid depends on our hp/no_water_days
    # If we're close to death, we must secure water.
    if my_hp <= 2 or my_no_water_days >= 2:
        urgency = 1.0
    elif my_hp <= 4 or my_no_water_days >= 1:
        urgency = 0.75
    else:
        urgency = 0.55

    # Supply scaling: higher supply reduces required aggressiveness.
    # supply in [15,25]
    supply_norm = 0.0
    try:
        supply_norm = (float(supply) - 15.0) / 10.0
    except Exception:
        supply_norm = 0.0
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Target bid: follow yesterday pressure but discount when supply is high.
    # Empirically, others bid around 80-130; we aim slightly below top pressure unless urgent.
    top_pressure = pressure
    if top_pressure <= 0.0:
        top_pressure = DAILY_SALARY * 0.6

    # Discount with supply_norm and urgency
    # When supply is high, we can bid less; when urgency is high, bid more.
    supply_discount = 0.85 - 0.25 * supply_norm  # ~0.85 at low supply, ~0.60 at high

    if urgency >= 0.9:
        target = top_pressure * 0.92
    elif urgency >= 0.7:
        target = max(DAILY_SALARY * 0.65, top_pressure * 0.80)
    else:
        target = max(DAILY_SALARY * 0.50, top_pressure * 0.70)

    target = target * supply_discount

    # Keep within budget and avoid extreme overbids.
    # Cap around 1.45*DAILY_SALARY to avoid catastrophic spending.
    cap = DAILY_SALARY * 1.45
    bid = float(min(my_budget, min(cap, target)))

    # If budget is very low, still bid enough to avoid wasting survival opportunities.
    if my_budget <= DAILY_SALARY * 0.25:
        bid = float(min(my_budget, DAILY_SALARY * 0.35))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    day = day_context['day']
    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        max_prev = 0
        avg_prev = 0
    if hp <= 3:
        target = max(DAILY_SALARY * 0.9, max_prev + 2)
    elif hp <= 5:
        target = max(DAILY_SALARY * 0.7, avg_prev + 1)
    else:
        target = DAILY_SALARY * 0.5
    # ensure not over budget
    bid = min(budget, target)
    # also ensure at least 0
    bid = max(0, bid)
    return bid
